// Get the initial data from the 'Prepare Video Request1' node
const prepData = $('Prepare Video Request').item.json;

// --- API Change: Convert Aspect Ratio ---
// Veo (old) used "16:9", Sora (new) uses "landscape"
const newAspectRatio = prepData.aspect_ratio === "16:9" ? "landscape" : "portrait";

let modelName = "";
let inputData = {};

// --- THIS IS THE FIX ---
// Check if an image exists
if (prepData.has_image) {
  // --- Image-to-Video Path ---
  modelName = "sora-2-image-to-video";

  // *Only* get the URL if an image exists
  const googleDriveUrl = $('Upload to Google Drive1').item.json.webContentLink;

  inputData = {
    prompt: prepData.prompt,
    image_urls: [googleDriveUrl],
    aspect_ratio: newAspectRatio,
    n_frames: "10",
    remove_watermark: true
  };

} else {
  // --- Text-to-Video Path ---
  modelName = "sora-2-text-to-video";

  inputData = {
    prompt: prepData.prompt,
    aspect_ratio: newAspectRatio,
    n_frames: "10",
    remove_watermark: true
  };
}

// Build the final request body
const api_request_body = {
  model: modelName,
  input: inputData
};

// Return all data for the next nodes
return {
  ...prepData,
  api_request_body: api_request_body
};

// Extract task ID and video ID from Kie.ai response
const response = $input.first().json;

// Kie.ai returns taskId in the data object
const taskId = response.data?.taskId || response.taskId;
const videoId = $('Prepare Video Request').item.json.video_id;

if (!taskId) {
  throw new Error('No task ID received from Kie.ai API');
}

return {
  task_id: taskId,
  video_id: videoId,
  raw_response: response
};

// Parse Kie.ai Sora 2 status response
const response = $input.first().json;

if (response.code !== 200) {
  throw new Error(`Kie.ai API error: ${response.msg}`);
}

const data = response.data;
const videoId = $('Extract Task ID').item.json.video_id;

// --- API Change: Check 'data.state' ---
// 'waiting', 'success', 'fail'
if (data.state === "fail") {
  throw new Error(`Video generation failed: ${data.failMsg || 'Unknown error'}`);
}

if (data.state === "success") {
  // --- API Change: Result is a JSON string ---
  if (!data.resultJson) {
     throw new Error('Video generation completed but no resultJson was returned');
  }

  const resultData = JSON.parse(data.resultJson);
  const videoUrls = resultData.resultUrls || [];

  if (videoUrls.length === 0) {
    throw new Error('Video generation completed but no video URL returned');
  }

  return {
    video_id: videoId,
    video_url: videoUrls[0],
    done: true,
    task_id: data.taskId
  };
}

// Still processing (data.state === "waiting")
return {
  video_id: videoId,
  done: false,
  task_id: data.taskId
};

