// Build the request body for Kie.ai Veo 3.1 Fast API
const requestBody = {
  prompt: $input.first().json.prompt,
  model: "veo3_fast",  // Use veo3_fast for 93% cost savings
  aspectRatio: $input.first().json.aspect_ratio,
  enableFallback: true,  // Enable fallback for better success rate
  enableTranslation: true  // Auto-translate non-English prompts
};

// Add image URL if exists (from previous upload or if provided)
if ($input.first().json.image_url) {
  requestBody.imageUrls = [$input.first().json.image_url];
}

return {
  prompt: $input.first().json.prompt,
  video_id: $input.first().json.video_id,
  aspect_ratio: $input.first().json.aspect_ratio,
  has_image: $input.first().json.has_image || false,
  api_request_body: requestBody
};

// --- THIS IS THE FIX ---
// Handle prompt from Form (json.Prompt) and Webhook (json.body.prompt)
const prompt = $input.first().json.Prompt || // From Form Trigger (Capital 'P')
               $input.first().json.prompt || // From JSON
               $input.first().json.body?.prompt; // From Webhook body

const videoId = $input.first().json.video_id || $input.first().json.body?.video_id || `video_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

// Handle aspect_ratio from Form (json['Aspect ratio']) and Webhook (json.body.aspect_ratio)
const aspectRatio = $input.first().json['Aspect ratio'] || // From Form Trigger
                      $input.first().json.aspect_ratio || // From JSON
                      $input.first().json.body?.aspect_ratio || // From Webhook body
                      "16:9";

// This is the full item (JSON + Binary) we will return
const returnItem = $input.first();

// This is the new JSON object we will build
let output = {
  prompt: prompt,
  video_id: videoId,
  aspect_ratio: aspectRatio
};

// Check for binary (image) data
if (returnItem.binary && Object.keys(returnItem.binary).length > 0) {
  const binaryKey = Object.keys(returnItem.binary)[0]; 
  const binaryData = returnItem.binary[binaryKey];

  const base64Image = binaryData.data;
  const mimeType = binaryData.mimeType || 'image/jpeg';

  output.image_base64 = base64Image;
  output.image_mime_type = mimeType;
  output.has_image = true;

  if (binaryKey !== 'data') {
    returnItem.binary.data = returnItem.binary[binaryKey];
    delete returnItem.binary[binaryKey];
  }

} else {
  output.has_image = false;
}

// Overwrite the item's original JSON with our new 'output' object
returnItem.json = output;

// Return the *entire item* (our new JSON + the original Binary)
return returnItem;

